      assert.throws(() => parseAge('151'), RangeError)
    })

    test('should throw RangeError when given "-1" (min-1)', () => {
      assert.throws(() => parseAge('-1'), RangeError)
    })

    test('should throw RangeError when given a numeric string far above range', () => {
      assert.throws(() => parseAge('999999999999999'), RangeError)
    })
  })

  describe('invalid input — spec requires RangeError, current source returns NaN instead (BUG)', () => {
    test('should throw RangeError when given empty string', () => {
      assert.throws(() => parseAge(''), RangeError)
    })

    test('should throw RangeError when given whitespace-only string', () => {
      assert.throws(() => parseAge('   '), RangeError)
    })

    test('should throw RangeError when given non-numeric string "abc"', () => {
      assert.throws(() => parseAge('abc'), RangeError)
    })

    test('should throw RangeError when given null', () => {
      assert.throws(() => parseAge(null), RangeError)
    })

    test('should throw RangeError when given undefined', () => {
      assert.throws(() => parseAge(undefined), RangeError)
    })

    test('should throw RangeError when given an object', () => {
      assert.throws(() => parseAge({}), RangeError)
    })

    test('should throw RangeError when given an array', () => {
      assert.throws(() => parseAge([]), RangeError)
    })

    test('should throw RangeError when given a boolean', () => {
      assert.throws(() => parseAge(true), RangeError)
    })

    test('should throw RangeError when given the string "Infinity"', () => {
      assert.throws(() => parseAge('Infinity'), RangeError)
    })

    test('should throw RangeError when given NaN directly', () => {
      assert.throws(() => parseAge(NaN), RangeError)
    })
  })

  describe('partial-parse garbage — spec requires full-string validation, current source truncates silently (BUG)', () => {
    test('should throw RangeError when given "12abc"', () => {
      assert.throws(() => parseAge('12abc'), RangeError)
    })

    test('should throw RangeError when given "150xyz"', () => {
      assert.throws(() => parseAge('150xyz'), RangeError)
    })

    test('should throw RangeError when given "0x10"', () => {
      assert.throws(() => parseAge('0x10'), RangeError)
    })
  })

  describe('documented current behavior (judgment call, not asserted as required)', () => {
    test('should return 10 (truncated) when given "10.9"', () => {
      assert.strictEqual(parseAge('10.9'), 10)
    })

    test('should return 42 when given the number 42 (implicit coercion)', () => {
      assert.strictEqual(parseAge(42), 42)
    })
  })

  describe('determinism', () => {
    test('should return the same result when called twice with the same input', () => {
      const first = parseAge('30')
      const second = parseAge('30')
      assert.strictEqual(first, second)
    })
